pub const fn aatrox_p(ctx: &Ctx) -> f32 {
    4.04 + 0.0035 * (-1.0 + ctx.level) + 6.0 * (-1.0 + ctx.level) / 17.0
}

pub const fn aatrox_qmin(ctx: &Ctx) -> f32 {
    37.5 + 56.25 * (-1.0 + ctx.q_level)
        + ctx.attack_damage * (0.6 + 0.075 * (-1.0 + ctx.q_level))
        + ctx.attack_damage * (0.75 + 0.09375 * (-1.0 + ctx.q_level))
        + ctx.attack_damage * (0.9 + 0.1125 * (-1.0 + ctx.q_level))
}

pub const fn aatrox_q1min(ctx: &Ctx) -> f32 {
    10.0 + 15.0 * (-1.0 + ctx.q_level)
        + ctx.attack_damage * (0.6 + 0.075 * (-1.0 + ctx.q_level))
}

pub const fn aatrox_q2min(ctx: &Ctx) -> f32 {
    12.5 + 18.75 * (-1.0 + ctx.q_level)
        + ctx.attack_damage * (0.75 + 0.09375 * (-1.0 + ctx.q_level))
}

pub const fn aatrox_q3min(ctx: &Ctx) -> f32 {
    15.0 + 22.5 * (-1.0 + ctx.q_level)
        + ctx.attack_damage * (0.9 + 0.1125 * (-1.0 + ctx.q_level))
}

pub const fn aatrox_qmax(ctx: &Ctx) -> f32 {
    63.75
        + 95.625 * (-1.0 + ctx.q_level)
        + ctx.attack_damage * (1.02 + 0.1275 * (-1.0 + ctx.q_level))
        + ctx.attack_damage * (1.275 + 0.159375 * (-1.0 + ctx.q_level))
        + ctx.attack_damage * (1.53 + 0.19125 * (-1.0 + ctx.q_level))
}

pub const fn aatrox_q1max(ctx: &Ctx) -> f32 {
    17.0 + 25.5 * (-1.0 + ctx.q_level)
        + ctx.attack_damage * (1.02 + 0.1275 * (-1.0 + ctx.q_level))
}

pub const fn aatrox_q2max(ctx: &Ctx) -> f32 {
    21.25
        + 31.875 * (-1.0 + ctx.q_level)
        + ctx.attack_damage * (1.275 + 0.159375 * (-1.0 + ctx.q_level))
}

pub const fn aatrox_q3max(ctx: &Ctx) -> f32 {
    25.5 + 38.25 * (-1.0 + ctx.q_level)
        + ctx.attack_damage * (1.53 + 0.19125 * (-1.0 + ctx.q_level))
}

pub const fn aatrox_wmin(ctx: &Ctx) -> f32 {
    10.0 * (2.0 + 0.04 * ctx.attack_damage + ctx.w_level)
}

pub const fn aatrox_wmax(ctx: &Ctx) -> f32 {
    20.0 * (2.0 + 0.04 * ctx.attack_damage + ctx.w_level)
}

