pub const fn akali_p(ctx: &Ctx) -> f32 {
    ((match ctx.level as u8 {
        ..=1 => 35.0,
        2 => 38.0,
        3 => 41.0,
        4 => 44.0,
        5 => 47.0,
        6 => 50.0,
        7 => 53.0,
        8 => 62.0,
        9 => 71.0,
        10 => 80.0,
        11 => 89.0,
        12 => 98.0,
        13 => 107.0,
        14 => 122.0,
        15 => 137.0,
        16 => 152.0,
        17 => 167.0,
        18 => 182.0,
        19 => 197.0,
        20.. => 212.0,
    }) + ((0.6) * ctx.bonus_ad))
        + ((0.55) * ctx.ability_power)
}

pub const fn akali_q(ctx: &Ctx) -> f32 {
    5.0 * (9.0
        + 0.12 * ctx.ability_power
        + 0.13 * ctx.attack_damage
        + 5.0 * (-1.0 + ctx.q_level))
}

pub const fn akali_emin(ctx: &Ctx) -> f32 {
    49.0 * (0.015714285714285715 * ctx.ability_power
        + 0.014285714285714285 * ctx.attack_damage
        + ctx.e_level)
}

pub const fn akali_emax(ctx: &Ctx) -> f32 {
    70.0 + 1.1 * ctx.ability_power
        + ctx.attack_damage
        + 70.0 * (-1.0 + ctx.e_level)
}

pub const fn akali_r1(ctx: &Ctx) -> f32 {
    110.0
        + 0.3 * ctx.ability_power
        + 55.0 * (-1.0 + ctx.r_level)
        + ctx.bonus_ad / 2.0
}

pub const fn akali_rmin(ctx: &Ctx) -> f32 {
    105.0 * (1.0 + 0.008571428571428572 * ctx.ability_power + ctx.r_level)
}

pub const fn akali_rmax(ctx: &Ctx) -> f32 {
    35.0 * (1.0 + 0.008571428571428572 * ctx.ability_power + ctx.r_level)
}

